"""Learner-facing checkbox generation requires a nonempty correct subset.

This module is also copied into immutable generator packages. Keep it free of
repository imports so registered packages remain relocatable and offline.
"""
from functools import wraps
import hashlib
import inspect

POLICY_VERSION = 'nonempty-checkbox-v1'
MAX_ATTEMPTS = 128

class EmptyCheckboxSelection(ValueError):
    pass

def _enum(value):
    return str(value.get(':db/ident') if isinstance(value, dict) else value)

def checkbox_selection(record):
    if not isinstance(record, dict):
        return []
    question = record.get('question', record)
    values = []
    for field in question.get(':question/answer-fields', []):
        if _enum(field.get(':answer-field/type')) != ':answer-field.type/checkbox':
            continue
        ref = field.get(':answer-field/correct')
        value = ref.get(':answer/value') if isinstance(ref, dict) else None
        if value is None:
            aid = ref.get(':answer/id') if isinstance(ref, dict) else ref[1] if isinstance(ref, (list, tuple)) else ref
            value = next(a[':answer/value'] for a in field.get(':answer-field/choices', [])
                         if str(a[':answer/id']) == str(aid))
        if value not in ('false', 'true'):
            raise ValueError('Checkbox correct answers must be text true or false')
        values.append(value == 'true')
    return values

def _evidence_only(record):
    generation = record.get('generation', {}) if isinstance(record, dict) else {}
    return generation.get('eligible_for_learning') is False or generation.get('raw_evidence') is True or generation.get('evidence_only') is True

def _invalid(record):
    if _evidence_only(record):
        return False
    values = checkbox_selection(record)
    return bool(values) and not any(values)

def _records(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict) and isinstance(value.get('records'), list):
        return value['records']
    return [value]

def _seed(seed, attempt, slot=0):
    text = f'{POLICY_VERSION}:{seed}:{attempt}:{slot}'.encode()
    return int.from_bytes(hashlib.sha256(text).digest()[:8], 'big')

def nonempty_checkbox(generator):
    """Preserve valid calls; deterministically resample empty seeded instances.

    Explicit mathematical parameters are never silently changed. Historical
    evidence-only replay remains readable; publication checks eligibility too.
    Batch replacements are generated individually rather than demanding that
    a whole large batch happen to contain no empty subsets on one seed.
    """
    if getattr(generator, '_nonempty_checkbox_policy', False):
        return generator
    signature = inspect.signature(generator)

    @wraps(generator)
    def checked(*args, **kwargs):
        bound = signature.bind(*args, **kwargs)
        bound.apply_defaults()
        seed = bound.arguments.get('seed')
        explicit = any(bound.arguments.get(name) is not None
                       for name in ('parameters', 'params', 'numbers', 'cases', 'decision_case', 'selection'))
        can_retry = 'seed' in signature.parameters and not explicit
        last_error = None
        for attempt in range(MAX_ATTEMPTS if can_retry else 1):
            if attempt:
                bound.arguments['seed'] = _seed(seed, attempt)
            try:
                result = generator(*bound.args, **bound.kwargs)
            except EmptyCheckboxSelection as error:
                last_error = error
                if can_retry:
                    continue
                raise
            records = _records(result)
            bad = [i for i, record in enumerate(records) if _invalid(record)]
            if bad and not can_retry:
                raise EmptyCheckboxSelection('Checkbox question has no correct selectable option; explicit parameters cannot be resampled')
            if bad and len(records) > 1 and 'count' in signature.parameters:
                for slot in bad:
                    for replacement in range(1, MAX_ATTEMPTS + 1):
                        single = signature.bind(*bound.args, **bound.kwargs)
                        single.arguments['count'] = 1
                        single.arguments['seed'] = _seed(seed, replacement, slot + 1)
                        try:
                            candidates = _records(generator(*single.args, **single.kwargs))
                        except EmptyCheckboxSelection:
                            continue
                        if len(candidates) == 1 and not _invalid(candidates[0]):
                            records[slot] = candidates[0]
                            break
                    else:
                        raise EmptyCheckboxSelection('No nonempty checkbox instance found for this batch slot')
                bad = []
            if bad:
                last_error = EmptyCheckboxSelection('Checkbox question has no correct selectable option')
                continue
            for record in records:
                if isinstance(record, dict) and checkbox_selection(record) and not _evidence_only(record):
                    record.setdefault('generation', {}).setdefault('checkbox_selection_policy', POLICY_VERSION)
            return result
        raise EmptyCheckboxSelection('No nonempty checkbox instance exists in the bounded sampling attempts') from last_error

    checked._nonempty_checkbox_policy = True
    return checked
//! Difficulty-first sampling. A task and its completed prefix seed a stable
//! draw, so rereading or retrying a continuation cannot reshuffle its question.
use crate::{Result, schema::EntitySnapshot};
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

const BANDS: [&str; 3] = ["easy", "moderate", "hard"];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phase {
    Initial,
    Remedial,
}

/// Lessons and reviews use their existing question-count phase rules.
/// Assessments must request a phase explicitly: a long quiz is not remedial.
pub fn weights(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    answered: usize,
) -> Result<Option<[f64; 3]>> {
    let initial_count = match activity_type {
        "lesson" => 2,
        "review" => 3,
        _ => return Err("question-count phases support lessons and reviews; assessments require an explicit phase".into()),
    };
    weights_for_phase(
        s,
        policy,
        activity_type,
        if answered < initial_count {
            Phase::Initial
        } else {
            Phase::Remedial
        },
    )
}

pub fn weights_for_phase(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    phase: Phase,
) -> Result<Option<[f64; 3]>> {
    if !matches!(activity_type, "lesson" | "review" | "assessment") {
        return Err("unsupported question-weight activity type".into());
    }
    let selected_phase = match phase {
        Phase::Initial => "initial",
        Phase::Remedial => "remedial",
    };
    let mut types = BTreeSet::new();
    let mut selected = None;
    for child in s.refs(policy, "policy/question-selection-weights")? {
        if s.owners(child, "policy/question-selection-weights")? != [policy] {
            return Err("question weights must have exactly one policy owner".into());
        }
        let kind = s.ident(&serde_json::json!(
            s.reference(child, "question-weights/activity-type")?
        ))?;
        if !matches!(
            kind.as_str(),
            "activity.type/lesson" | "activity.type/review" | "activity.type/assessment"
        ) || !types.insert(kind.clone())
        {
            return Err(
                "policy needs at most one question-weight record per supported activity type"
                    .into(),
            );
        }
        for phase in ["initial", "remedial"] {
            let mut distribution = [0.0; 3];
            for (index, band) in BANDS.iter().enumerate() {
                let key = format!("question-weights/{phase}-{band}");
                distribution[index] = s
                    .entity(child)?
                    .get(&key)
                    .and_then(|v| v.as_f64())
                    .filter(|v| v.is_finite() && *v >= 0.0)
                    .ok_or_else(|| format!("{key} must be finite and nonnegative"))?;
            }
            let total: f64 = distribution.iter().sum();
            if !total.is_finite() || total <= 0.0 {
                return Err(
                    "each question-weight distribution needs a positive finite total".into(),
                );
            }
            if kind == format!("activity.type/{activity_type}") && phase == selected_phase {
                selected = Some(distribution);
            }
        }
    }
    Ok(selected)
}

pub fn active_policy(s: &EntitySnapshot) -> Result<u64> {
    let policies = s.entities.with_attribute("policy/id");
    match policies.as_slice() {
        [policy] => Ok(*policy),
        _ => Err("question selection requires exactly one configured policy".into()),
    }
}

/// Exclude previous tasks; the caller separately excludes its current prefix.
/// This also lets completion validate an already-reserved current question.
pub fn seen_before_task(s: &EntitySnapshot, learner: u64, task: u64) -> Result<BTreeSet<u64>> {
    let mut seen = BTreeSet::new();
    for other in s.refs(learner, "learner/activity")? {
        if other == task {
            continue;
        }
        for item in s.refs(other, "learner-task/items")? {
            if let Some(content) = s.optional_ref(item, "task-item/content")? {
                seen.insert(content);
            }
        }
    }
    Ok(seen)
}

/// Candidates must already be fresh and usable. Unknown ratings are a uniform
/// fallback only when no eligible, positively weighted rated band remains.
/// Explicitly zero-weight rated bands are never used as that fallback.
pub fn select(
    s: &EntitySnapshot,
    candidates: &[u64],
    distribution: Option<[f64; 3]>,
    seed: &str,
) -> Result<Option<u64>> {
    let candidates: Vec<_> = candidates
        .iter()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    // Preserve old, unconfigured policies; the default policy supplies weights.
    let Some(distribution) = distribution else {
        return Ok(candidates.first().copied());
    };
    if distribution.iter().any(|w| !w.is_finite() || *w < 0.0)
        || !distribution.iter().sum::<f64>().is_finite()
        || distribution.iter().sum::<f64>() <= 0.0
    {
        return Err("invalid question-weight distribution".into());
    }
    let mut bands: [Vec<u64>; 3] = std::array::from_fn(|_| vec![]);
    let mut unrated = vec![];
    for q in candidates {
        let Some(value) = s
            .entity(q)?
            .get("question/difficulty")
            .filter(|v| !v.is_null())
        else {
            unrated.push(q);
            continue;
        };
        let difficulty = s.ident(value)?;
        let band = BANDS
            .iter()
            .position(|b| difficulty == format!("question.difficulty/{b}"))
            .ok_or("question has an unsupported difficulty enum")?;
        bands[band].push(q);
    }
    let digest = Sha256::digest(format!("course-academy/question-selection/v1/{seed}"));
    let uniform = |offset| {
        let bits = u64::from_be_bytes(digest[offset..offset + 8].try_into().unwrap()) >> 11;
        bits as f64 / (1u64 << 53) as f64
    };
    let total: f64 = distribution
        .iter()
        .enumerate()
        .filter(|(i, _)| !bands[*i].is_empty())
        .map(|(_, w)| *w)
        .sum();
    let pool = if total > 0.0 {
        let mut draw = uniform(0) * total;
        let mut chosen = None;
        for (i, w) in distribution.iter().enumerate() {
            if bands[i].is_empty() || *w == 0.0 {
                continue;
            }
            chosen = Some(i);
            if draw < *w {
                break;
            }
            draw -= *w;
        }
        &bands[chosen.unwrap()]
    } else {
        &unrated
    };
    Ok(if pool.is_empty() {
        None
    } else {
        Some(pool[(uniform(8) * pool.len() as f64) as usize])
    })
}

